import { Scene, PlayerControls } from "retiam";

const scene = new Scene({ canvas });
// ... construct animations ...

// Mount player controls over the scene canvas
const controls = new PlayerControls(scene, {
    autoHide: true,     // Fades out toolbar during idle cursor
    showSpeed: true,
    showLoop: true,
    showStep: true
});

export interface SliderControlOption {
    type: 'slider';
    label: string;
    value: number;
    min?: number;
    max?: number;
    step?: number;
    onChange: (value: number) => void;
}

export type ControlOption = SliderControlOption;

export interface ControlPanelOptions {
    title?: string;
    parent?: HTMLElement;
    controls: ControlOption[];
}

import { Scene, NumberPlane, ControlPanel, ValueTracker } from "retiam";

const scene = new Scene({ canvas });
const frequency = new ValueTracker(2.0);
const amplitude = new ValueTracker(1.0);

// Interactive control panel modifying mathematical wave parameters
const panel = new ControlPanel({
    title: "Waveform Parameters",
    controls: [
        {
            type: "slider",
            label: "Frequency (Hz)",
            value: 2.0,
            min: 0.1,
            max: 10.0,
            step: 0.1,
            onChange: (v) => { frequency.value = v; }
        },
        {
            type: "slider",
            label: "Amplitude",
            value: 1.0,
            min: 0.0,
            max: 5.0,
            step: 0.05,
            onChange: (v) => { amplitude.value = v; }
        }
    ]
});
